// Particle component representing floating ideas / letters rising from the book
const Particle: React.FC<{
  index: number;
  frame: number;
  width: number;
  height: number;
}> = ({ index, frame, width, height }) => {
  const seed1 = seededRandom(index + 1);
  const seed2 = seededRandom(index + 2);
  const seed3 = seededRandom(index + 3);

  const lifetime = 100; // frames
  const delay = seed1 * 120;
  const progress = ((frame - delay) % lifetime) / lifetime;

  if (frame < delay) return null;

  // Float upwards and sway side to side
  const startX = width * 0.22 + (seed2 - 0.5) * 100;
  const startY = height * 0.62;
  const currentY = startY - progress * 160 - seed3 * 40;
  const currentX = startX + Math.sin(progress * 6 + seed1 * 4) * 20;

  const opacity = interpolate(progress, [0, 0.15, 0.8, 1], [0, 1, 1, 0]);
  const scale = interpolate(progress, [0, 0.15, 1], [0.4, 1, 0.5]);

  const items = ["A", "B", "C", "1", "2", "3", "✎", "★", "♫", "📚", "α", "π"];
  const char = items[Math.floor(seed1 * items.length)];

  return (
    <div
      style={{
        position: "absolute",
        left: currentX,
        top: currentY,
        opacity,
        transform: `scale(${scale})`,
        fontSize: "22px",
        color: "#ffffff",
        fontWeight: "bold",
        fontFamily: spaceGroteskFont,
        pointerEvents: "none",
        textShadow: "0 2px 5px rgba(0,0,0,0.3)",
        transition: "none",
      }}
    >
      {char}
    </div>
  );
};

