const SplitScreenIllustration: React.FC<SplitScreenIllustrationProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 10,
  backgroundColorLeft = "#2e4a4f",
  backgroundColorRight = "#f3f1eb",
  dividerColor = "#ffffff",
  leftTitle = "CURIOSITY & FOCUS",
  leftSubtitle = "Nurturing the mind through literature",
  rightTitle = "ENERGY & PLAY",
  rightSubtitle = "Building strength through active movement",
  textPrimaryColorLeft = "#ffffff",
  textSecondaryColorLeft = "#a7c2c6",
  textPrimaryColorRight = "#2d3e40",
  textSecondaryColorRight = "#7a8587",
  showGridOverlays = true,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const finalBgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Timings and Spring Animations
  const dividerReveal = spring({
    frame,
    fps,
    config: { damping: 16, stiffness: 90 },
  });

  const contentSpringLeft = spring({
    frame: frame - 8,
    fps,
    config: { damping: 15, stiffness: 80 },
  });

  const contentSpringRight = spring({
    frame: frame - 14,
    fps,
    config: { damping: 15, stiffness: 80 },
  });

  // Slide factors
  const leftX = interpolate(contentSpringLeft, [0, 1], [-180, 0], {
    extrapolateRight: "clamp",
  });
  const leftOpacity = interpolate(contentSpringLeft, [0, 1], [0, 1], {
    extrapolateRight: "clamp",
  });

  const rightX = interpolate(contentSpringRight, [0, 1], [180, 0], {
    extrapolateRight: "clamp",
  });
  const rightOpacity = interpolate(contentSpringRight, [0, 1], [0, 1], {
    extrapolateRight: "clamp",
  });

  // Staggered text reveal
  const textSpringLeft = spring({
    frame: frame - 22,
    fps,
    config: { damping: 12 },
  });
  const textLeftY = interpolate(textSpringLeft, [0, 1], [30, 0], {
    extrapolateRight: "clamp",
  });
  const textLeftOpacity = interpolate(textSpringLeft, [0, 1], [0, 1], {
    extrapolateRight: "clamp",
  });

  const textSpringRight = spring({
    frame: frame - 28,
    fps,
    config: { damping: 12 },
  });
  const textRightY = interpolate(textSpringRight, [0, 1], [30, 0], {
    extrapolateRight: "clamp",
  });
  const textRightOpacity = interpolate(textSpringRight, [0, 1], [0, 1], {
    extrapolateRight: "clamp",
  });

  // Diagonal Divider specs
  const tiltDegrees = 2.5;

  return (
    <AbsoluteFill
      style={{ backgroundColor: finalBgColor, overflow: "hidden" }}
    >
      {/* LEFT SPLIT PANEL */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          height: "100%",
          backgroundColor: backgroundColorLeft,
          clipPath: "polygon(0 0, 52% 0, 48% 100%, 0 100%)",
          zIndex: 5,
          transition: "none",
        }}
      >
        <div
          style={{
            width: "100%",
            height: "100%",
            transform: `translateX(${leftX}px)`,
            opacity: leftOpacity,
            position: "absolute",
            transition: "none",
          }}
        >
          {/* Decorative Teal Circle */}
          <div
            style={{
              position: "absolute",
              top: "45%",
              left: "10%",
              width: "55px",
              height: "55px",
              borderRadius: "50%",
              backgroundColor: "#22383c",
              opacity: 0.6,
              transition: "none",
            }}
          />

          {/* Dot Grid overlay */}
          {showGridOverlays && (
            <div
              style={{
                position: "absolute",
                top: "18%",
                left: "8%",
                opacity: 0.25,
                transition: "none",
              }}
            >
              <DotGrid rows={5} cols={4} color="#85a4a9" />
            </div>
          )}

          {/* Girl reading and writing Illustration */}
          <GirlIllustration frame={frame} width={width} height={height} />

          {/* Floating Ideas/Letters */}
          {Array.from({ length: 8 }).map((_, i) => (
            <Particle
              key={i}
              index={i}
              frame={frame}
              width={width}
              height={height}
            />
          ))}

          {/* Left Title Card */}
          <div
            style={{
              position: "absolute",
              top: "10%",
              left: "10%",
              maxWidth: "38%",
              transform: `translateY(${textLeftY}px)`,
              opacity: textLeftOpacity,
              transition: "none",
            }}
          >
            <h2
              style={{
                fontFamily: playfairFont,
                color: textPrimaryColorLeft,
                fontSize: "44px",
                margin: 0,
                letterSpacing: "0.5px",
                lineHeight: 1.15,
                textTransform: "uppercase",
                transition: "none",
              }}
            >
              {leftTitle}
            </h2>
            <p
              style={{
                fontFamily: spaceGroteskFont,
                color: textSecondaryColorLeft,
                fontSize: "18px",
                marginTop: "10px",
                fontWeight: 300,
                lineHeight: 1.4,
                transition: "none",
              }}
            >
              {leftSubtitle}
            </p>
          </div>
        </div>
      </div>

      {/* RIGHT SPLIT PANEL */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          height: "100%",
          backgroundColor: backgroundColorRight,
          clipPath: "polygon(52% 0, 100% 0, 100% 100%, 48% 100%)",
          zIndex: 4,
          transition: "none",
        }}
      >
        <div
          style={{
            width: "100%",
            height: "100%",
            transform: `translateX(${rightX}px)`,
            opacity: rightOpacity,
            position: "absolute",
            transition: "none",
          }}
        >
          {/* Big Editorial Cream Accent Circle */}
          <div
            style={{
              position: "absolute",
              top: "24%",
              right: "8%",
              width: "250px",
              height: "250px",
              borderRadius: "50%",
              backgroundColor: "#ebdcb9",
              opacity: 0.8,
              transition: "none",
            }}
          />

          {/* Sage Accent Circle */}
          <div
            style={{
              position: "absolute",
              bottom: "8%",
              left: "53%",
              width: "68px",
              height: "68px",
              borderRadius: "50%",
              backgroundColor: "#8c9f8d",
              opacity: 0.9,
              transition: "none",
            }}
          />

          {/* Dot Grid overlay */}
          {showGridOverlays && (
            <div
              style={{
                position: "absolute",
                top: "15%",
                right: "8%",
                opacity: 0.55,
                transition: "none",
              }}
            >
              <DotGrid rows={5} cols={4} color="#a1aba4" />
            </div>
          )}

          {/* Boy playing soccer Illustration */}
          <BoyIllustration frame={frame} width={width} height={height} />

          {/* Right Title Card */}
          <div
            style={{
              position: "absolute",
              top: "10%",
              right: "10%",
              maxWidth: "38%",
              textAlign: "right",
              transform: `translateY(${textRightY}px)`,
              opacity: textRightOpacity,
              transition: "none",
            }}
          >
            <h2
              style={{
                fontFamily: spaceGroteskFont,
                color: textPrimaryColorRight,
                fontSize: "44px",
                margin: 0,
                letterSpacing: "-0.5px",
                lineHeight: 1.15,
                textTransform: "uppercase",
                transition: "none",
              }}
            >
              {rightTitle}
            </h2>
            <p
              style={{
                fontFamily: spaceGroteskFont,
                color: textSecondaryColorRight,
                fontSize: "18px",
                marginTop: "10px",
                fontWeight: 400,
                lineHeight: 1.4,
                transition: "none",
              }}
            >
              {rightSubtitle}
            </p>
          </div>
        </div>
      </div>

      {/* ANGLED SEPARATOR LINE */}
      <div
        style={{
          position: "absolute",
          top: "-5%",
          bottom: "-5%",
          left: "50%",
          width: "8px",
          backgroundColor: dividerColor,
          transform: `translateX(-50%) rotate(${tiltDegrees}deg) scaleY(${dividerReveal})`,
          zIndex: 10,
          boxShadow: "0 0 15px rgba(0,0,0,0.1)",
          transformOrigin: "center",
          transition: "none",
        }}
      />
    </AbsoluteFill>
  );
};

export default SplitScreenIllustration;